insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('AO', 'default', 'Plano Geral de Contabilidade (PGC) — selecção para sociedades comerciais', '{}'::jsonb, true, 'companies', array['AO-PGC-BAL', 'AO-PGC-DR']::text[], null, 'Decreto n.º 82/01, de 16 de novembro, approves the Plano Geral de Contabilidade, the legal chart of accounts of Angola. It applies to companies other than banks and insurers, which follow their own regimes (the International Financial Reporting Standards for banks); the IFRS complement the plan. The chart carries the official codes and names of classes 1 to 8, with the dots removed from each code (34.5.3.1 is 34531), at the level of detail a trading company posts to. The VAT sub-accounts of account 34.5 come from Decreto Presidencial n.º 180/19, de 24 de maio. Where this pack adds a level the plan leaves free, it says so in the name or in the README: 7581 Arredondamentos (rounding) and 3791 IVA de importação a pagar à alfândega (import VAT owed to customs).', 'pgc-82-01')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

