insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('AO', 'AO-P-14-BL', 'Aquisição à taxa geral (14 %), IVA não dedutível', '{}'::jsonb, 'Tax charged on an expense the code excludes from the right to deduct', 'percent', 14, 'purchase', 'domestic', date '2019-10-01', null, 'Código do IVA, Capítulo V (right to deduct) — the tax charged on an expense the code excludes from deduction (for instance passenger cars and entertainment) is not deducted and is not declared: it adds to the cost of the line. Nothing is reported in the Modelo 7.', null, null, 170, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-14-EXI', 'Compra de existências à taxa geral (14 %), dedutível', '{}'::jsonb, 'Goods for resale or consumption in production', 'percent', 14, 'purchase', 'domestic', date '2019-10-01', null, 'Código do IVA, art. 19.º — 14 % — and the right to deduct of the Capítulo V. Modelo 7, quadro 9, fields 18 (base) and 19 (tax in favour of the taxpayer) — acquisitions of inventories.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-14-MFI', 'Compra de meios fixos e investimentos à taxa geral (14 %), dedutível', '{}'::jsonb, 'Equipment and other fixed assets', 'percent', 14, 'purchase', 'domestic', date '2019-10-01', null, 'Código do IVA, art. 19.º — 14 %. Modelo 7, quadro 9, fields 16 (base) and 17 (tax in favour of the taxpayer) — acquisitions of fixed assets and investments.', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-14-OUT', 'Compra de outros bens de consumo à taxa geral (14 %), dedutível', '{}'::jsonb, 'Consumables and other goods that are neither inventory nor fixed assets', 'percent', 14, 'purchase', 'domestic', date '2019-10-01', null, 'Código do IVA, art. 19.º — 14 %. Modelo 7, quadro 9, fields 20 (base) and 21 (tax in favour of the taxpayer) — acquisitions of other consumable goods.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-14-SERV', 'Aquisição de serviços à taxa geral (14 %), dedutível', '{}'::jsonb, 'Services bought from a supplier established in Angola', 'percent', 14, 'purchase', 'domestic', date '2019-10-01', null, 'Código do IVA, art. 19.º — 14 %. Modelo 7, quadro 9, fields 22 (base) and 23 (tax in favour of the taxpayer) — acquisitions of services.', null, null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-5-EXI', 'Compra de existências a 5 %, dedutível', '{}'::jsonb, 'Foodstuffs and agricultural inputs bought at the reduced rate', 'percent', 5, 'purchase', 'domestic', date '2024-01-01', null, 'Código do IVA, art. 19.º, Anexos I and II — 5 %. Modelo 7, quadro 9, fields 18 (base) and 19 (tax in favour of the taxpayer) — acquisitions of inventories.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-EX', 'Aquisição isenta ou não tributada', '{}'::jsonb, 'Bank charges, medicines and other exempt purchases', 'percent', 0, 'purchase', 'exempt', date '2019-10-01', null, 'Código do IVA, art. 12.º — a purchase of a supply the code exempts, such as bank charges: no tax is charged and the Modelo 7 reports nothing.', null, null, 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-EXT-14', 'Serviço adquirido a prestador não residente (14 %), autoliquidado', '{}'::jsonb, 'A service bought abroad; the buyer charges and deducts the tax on the same return', 'percent', 14, 'purchase', 'foreign_services_received', date '2019-10-01', null, 'Código do IVA, art. 29.º — the recipient, a taxable person, accounts for the tax on a service supplied by a provider with no seat, permanent establishment or domicile in Angola. Modelo 7, quadro 9, fields 13 (base), 15 (tax in favour of the State) and 14 (the same tax deductible in favour of the taxpayer): the two net to zero when the right to deduct is complete.', null, null, 200, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-P-IMP-14', 'Importação de bens à taxa geral (14 %), liquidada pela alfândega', '{}'::jsonb, 'Goods imported for home consumption; the customs collect the tax', 'percent', 14, 'purchase', 'import', date '2019-10-01', null, 'Código do IVA, art. 19.º — 14 % on imports; the tax is assessed and collected by the customs services on the import declaration and is deductible. Modelo 7, quadro 9, fields 24 (base) and 25 (deductible tax paid on imports). The tax is owed to customs on account 3791 until paid.', null, null, 190, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-1-CAB', 'Regime especial da província de Cabinda (1 %)', '{}'::jsonb, 'Special regime of Cabinda, 1 % since 1 January 2024', 'percent', 1, 'sale', 'domestic', date '2024-01-01', null, 'Código do IVA, art. 19.º, as republished by the Lei n.º 14/23 — 1 % on imports and supplies of goods subject to the special regime of the province of Cabinda, the goods of Anexo III excepted, which pay the general rate. The page of the Portal do Contribuinte still shows 2 %; the Lei n.º 14/23 prevails. Modelo 7, quadro 9, line 1 — transactions on which the taxpayer charged tax: field 01 (taxable base) and field 02 (tax in favour of the State).', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-14', 'Venda ou serviço à taxa geral (14 %)', '{}'::jsonb, 'The general rate, charged on every taxable supply that no other code of this pack covers', 'percent', 14, 'sale', 'domestic', date '2019-10-01', null, 'Código do IVA, art. 19.º, as republished by the Lei n.º 14/23 — 14 % on imports, supplies of goods and services, the general rate since the VAT replaced the consumption tax on 1 October 2019. Modelo 7, quadro 9, line 1 — transactions on which the taxpayer charged tax: field 01 (taxable base) and field 02 (tax in favour of the State).', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-5', 'Bens alimentares de amplo consumo e insumos agrícolas (5 %)', '{}'::jsonb, 'Reduced rate for the goods of Anexos I and II, since 1 January 2024', 'percent', 5, 'sale', 'domestic', date '2024-01-01', null, 'Código do IVA, art. 19.º, as republished by the Lei n.º 14/23, and its Anexos I and II — 5 % on imports and supplies of widely consumed foodstuffs (meat, fish, milk, eggs, vegetables, fruit, cereals, flour, edible oils, sugar, bread, salt, water) and of agricultural inputs (seeds, fertilisers, tractors, fishing boats); the Ministry of Finance announced the reduction from 7 % on 1 January 2024. Modelo 7, quadro 9, line 1 — transactions on which the taxpayer charged tax: field 01 (taxable base) and field 02 (tax in favour of the State).', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-5-IND', 'Equipamentos industriais do fabricante (5 %)', '{}'::jsonb, 'Industrial equipment supplied by its manufacturer under an approval of the tax administration', 'percent', 5, 'sale', 'domestic', date '2026-01-01', null, 'Lei n.º 14/25 (Orçamento Geral do Estado para 2026), art. 23.º — the VAT rate on the import or supply of industrial equipment by the manufacturer is reduced to 5 %, after a procedure and verification by the tax administration that the equipment is industrial and has the declared purpose. The code is chosen only by a taxpayer who holds that approval. Modelo 7, quadro 9, line 1 — transactions on which the taxpayer charged tax: field 01 (taxable base) and field 02 (tax in favour of the State).', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'oge-2026', null, null, null, null),
  ('AO', 'AO-S-7-CB', 'Cesta básica (7 %) — taxa encerrada em 31/12/2023', '{}'::jsonb, 'Closed rate, kept for the documents dated 2022 and 2023', 'percent', 7, 'sale', 'domestic', date '2022-01-01', date '2023-12-31', 'Orçamento Geral do Estado para 2022 (Lei n.º 32/21) — the temporary 7 % on the goods of the basic basket (sugar, flour, beans, eggs, bread, fish, milk, cooking oil, salt, soap…), reduced from 14 %; it applied from 1 January 2022 until the rate of 5 % replaced it on 1 January 2024, so the code is closed and is kept to read documents of those two years. Modelo 7, quadro 9, line 1 — transactions on which the taxpayer charged tax: field 01 (taxable base) and field 02 (tax in favour of the State).', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'plmj-iva-7', null, null, null, null),
  ('AO', 'AO-S-7-HR', 'Hotelaria e restauração (7 %)', '{}'::jsonb, 'Reduced rate for hotel and restaurant services, in force since 1 January 2024', 'percent', 7, 'sale', 'domestic', date '2024-01-01', null, 'Código do IVA, art. 19.º, as republished by the Lei n.º 14/23 — 7 % on accommodation (hotelaria) and catering (restauração) services. Modelo 7, quadro 9, line 1 — transactions on which the taxpayer charged tax: field 01 (taxable base) and field 02 (tax in favour of the State).', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-7-SIMP', 'Regime simplificado (7 %) — taxa do contribuinte', '{}'::jsonb, 'Charged by a taxpayer of the simplified regime on all its supplies; documented as a separate code, never applied by default', 'percent', 7, 'sale', 'domestic', date '2024-01-01', null, 'Código do IVA, art. 69.º-A and art. 19.º, as republished by the Lei n.º 14/23 — a taxable person whose turnover or imports in the previous year were at least Kz 25,000,000 and under Kz 350,000,000 is in the simplified regime and charges 7 %. This is a rate of the taxpayer''s regime and not of the product: the code is never chosen by default, only by a company in that regime, and the pack does not model the regime''s 10 % input-tax allowance. The page of the Portal do Contribuinte still shows the 3 % of the earlier text; the Lei n.º 14/23 prevails. Modelo 7, quadro 9, line 1 — transactions on which the taxpayer charged tax: field 01 (taxable base) and field 02 (tax in favour of the State).', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-EX', 'Operação interna isenta, sem direito à dedução', '{}'::jsonb, 'Supplies the Código do IVA exempts, such as medicines, education, health care, letting of property and financial services', 'percent', 0, 'sale', 'exempt', date '2019-10-01', null, 'Código do IVA, art. 12.º, as republished by the Lei n.º 14/23 — domestic exemptions: books (also digital), wheelchairs for disabled people, letting of immovable property other than hotel accommodation, transfer of immovable property, collective passenger transport, education by establishments within the Lei de Bases, medical and health services other than aesthetic ones, the medical equipment of Anexo IV, medicines, financial services. Modelo 7, quadro 9, field 11 — exempt without the right to deduct (article 12 excluding its sub-paragraph a).', null, null, 90, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-EX-MOB', 'Pagamentos por plataformas móveis autorizadas, isentos', '{}'::jsonb, 'Fees of a transaction through a payment platform the central bank authorises', 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Lei n.º 14/25 (Orçamento Geral do Estado para 2026), art. 35.º — transactions made through mobile payment and instant transfer platforms duly authorised by the Banco Nacional de Angola are exempt from VAT and stamp duty. Reported with the other exempt supplies, Modelo 7, quadro 9, field 11; the placement in that line is this pack''s reading and is flagged for review in the README.', null, null, 100, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'oge-2026', null, null, null, null),
  ('AO', 'AO-S-EXP', 'Exportação, isenta com direito à dedução', '{}'::jsonb, 'Goods leaving Angola, with the transport evidence the customs require', 'percent', 0, 'sale', 'export', date '2019-10-01', null, 'Código do IVA, art. 15.º — supplies of goods dispatched or transported abroad by the exporter are exempt, with the right to deduct the input tax. Modelo 7, quadro 9, field 10 — transactions on which no tax was charged, exempt with the right to deduct; the specimen of the form lists exports (field 45) as a detail of that line.', null, null, 80, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null),
  ('AO', 'AO-S-NS', 'Operação não tributada (artigo 10.º)', '{}'::jsonb, 'A service rendered to a recipient abroad, outside the scope of the tax', 'percent', 0, 'sale', 'not_subject', date '2019-10-01', null, 'Código do IVA, art. 10.º — operations outside the scope of the tax, such as a service whose place of supply is outside Angola. Modelo 7, quadro 9, field 12 — non-taxed operations.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-14-23', null, null, null, null)
