insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('AO', 'AO-MODELO7', 'Declaração Periódica do IVA (Modelo 7)', array['month']::declaration_period[], 'month'::declaration_period, date '2019-10-01', null, 'Código do IVA, art. 44.º — taxable persons submit the periodic declaration by electronic transmission of data, and the system generates the Nota de Liquidação when tax is due. The form is the Modelo 7, filed on the Portal do Contribuinte of the Administração Geral Tributária, with the annexes of suppliers (and of customers where required) and, outside the e-invoicing regime, the SAF-T (AO) files of invoicing. The pack carries the general-regime part of the form (quadro 9, fields 01 to 37); the boxes of the cash-accounting regime and of withheld tax are carried without a tax code that writes into them. Two printings of the form exist (one with fields 26 and 27 headed «regularizações do imposto cativo», one with them headed «regularizações notificadas pela AGT» and an extra field 30); this pack follows the first.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Código do IVA, art. 44.º — the declaration is submitted by the last day of the month following the one to which the operations relate, whether or not taxable operations took place; the Modelo 7 itself reads «a submeter até ao último dia de cada mês respeitante às operações realizadas do mês anterior». The tax is paid by the same date through the Nota de Liquidação; some commentaries speak of the last working day, which Ekwo''s rule (the last calendar day) does not see.', 'civa-lei-7-19', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

