update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Decreto Presidencial n.º 71/25, art. 10.º, n.º 1, alínea b) — an invoice carries a sequential and chronological number by type of document and economic year, in one or more identified series. The style is `sequential` and the number restarts each year, as the format carries the year.',
  numbering_source_key          = 'dp-71-25',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Código do IVA (Lei n.º 7/19, as republished by the Lei n.º 14/23), art. 11.º — the tax is due and chargeable when the goods are placed at the disposal of the buyer or when the service is performed; for continuous supplies with periodic payments, at the end of each period. `delivery_date` is the closest value of Ekwo''s vocabulary; the special rules on advances, which the Modelo 7 reports in field 41, are not modelled and are recorded in the README.',
  tax_point_source_key          = 'civa-lei-7-19',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Angola has no Peppol authority, no published structured-invoice profile and no ISO 6523 scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. What Angola has instead is a clearance-style system: Decreto Presidencial n.º 71/25, art. 16.º, makes electronic invoicing mandatory for taxpayers of the general and simplified VAT regimes; art. 17.º requires invoicing software validated or provided by the Administração Geral Tributária (AGT) that transmits each invoice to it in real time; art. 37.º phases the obligation in — large taxpayers and suppliers of the State first, from 1 January 2026, then every taxpayer subject to it, from 1 January 2027 as the tax administration announced. That is a real-time reporting of each invoice to the tax administration, not a peer-to-peer exchange between businesses in the sense `einvoicing.profile` describes. Ekwo does not connect to the AGT platform; the gap is recorded in docs/international.md and in this pack''s README.',
  einvoice_source_key           = 'dp-71-25',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'AO';
